class InputCell(Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        _propagate(self)


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = inputs
        self._compute_function = compute_function
        self._callbacks = []
        for input_cell in inputs:
            input_cell._add_dependent(self)
        self._value = compute_function([cell.value for cell in inputs])

    @property
    def value(self):
        return self._value

    def _recompute(self):
        new_value = self._compute_function([cell.value for cell in self._inputs])
        self._changed = new_value != self._value
        self._value = new_value

    def _fire_callbacks_if_changed(self):
        if self._changed:
            for callback in self._callbacks:
                callback(self._value)

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)


def _propagate(source):
    # Collect every compute cell downstream of `source` in topological order
    # (dependencies before dependents) via reverse post-order DFS.
    post_order = []
    visited = set()

    def visit(cell):
        for dependent in cell._dependents:
            if id(dependent) not in visited:
                visited.add(id(dependent))
                visit(dependent)
                post_order.append(dependent)

    visit(source)
    ordered = list(reversed(post_order))

    # Recompute everything first so each cell sees its dependencies' final
    # values, then fire callbacks only for cells whose stable value changed.
    for cell in ordered:
        cell._recompute()
    for cell in ordered:
        cell._fire_callbacks_if_changed()
